import numpy as np
from .base import BaseLayer

class ReLU(BaseLayer):
    """Rectified Linear Unit activation function."""

    def __init__(self):
        super().__init__()

    def forward(self, x: np.ndarray) -> np.ndarray:
        """Forward pass: output = max(0, x)."""
        return np.maximum(0, x)

class LeakyReLU(BaseLayer):
    """Leaky Rectified Linear Unit activation function."""

    def __init__(self, negative_slope: float = 0.01):
        super().__init__()
        self.negative_slope = negative_slope

    def forward(self, x: np.ndarray) -> np.ndarray:
        """Forward pass: output = x if x > 0 else negative_slope * x."""
        return np.where(x > 0, x, self.negative_slope * x)

class Sigmoid(BaseLayer):
    """Sigmoid activation function."""

    def __init__(self):
        super().__init__()

    def forward(self, x: np.ndarray) -> np.ndarray:
        """Forward pass: output = 1 / (1 + exp(-x))."""
        # Use numerically stable computation
        # For large positive x: exp(-x) ≈ 0, output ≈ 1
        # For large negative x: exp(-x) ≈ 0, output ≈ 0
        max_x = np.max(x)
        shifted_x = x - max_x  # Shift to avoid overflow
        exp_neg_x = np.exp(-shifted_x)
        return 1.0 / (1.0 + exp_neg_x)
